; Separate js65 project that extracts the CHR data from a vanilla rom
; if any of the chr files are missing, this will attempt to extract
; it from any of the *.nes files that match the SMB1 crc
;
; The tile layout of each file is CHR_MAP in chr/chr_map.js, which is generated by
; src/gen/gen_chr_map.s (see that file for how to run it).
; New files also need a .segment below and an entry in .gitignore.

.segment "BG_COMMON"       :mem 0 :size $1000 :off 0 :out "chr/bg_common.chr"
.segment "BG_WATER"        :mem 0 :size $1000 :off 0 :out "chr/bg_water.chr"
.segment "BG_GROUND"       :mem 0 :size $1000 :off 0 :out "chr/bg_ground.chr"
.segment "BG_UNDERGROUND"  :mem 0 :size $1000 :off 0 :out "chr/bg_underground.chr"
.segment "BG_CASTLE"       :mem 0 :size $1000 :off 0 :out "chr/bg_castle.chr"
.segment "SPRITES_MARIO"   :mem 0 :size $1000 :off 0 :out "chr/sprites_mario.chr"
.segment "SPRITES_MISC"    :mem 0 :size $1000 :off 0 :out "chr/sprites_misc.chr"
.segment "SPRITES_ENEMIES" :mem 0 :size $1000 :off 0 :out "chr/sprites_enemies.chr"
.segment "SPRITES_CASTLE"  :mem 0 :size $1000 :off 0 :out "chr/sprites_castle.chr"

.jsinput chrfiles, "chr/*.chr"
.jsinput roms, "*.nes"
.jsinclude "chr/chr_map.js"
.jsinclude "src/gen/chr_tools.js"
.jsbegin
function buildChr(romChr, map) {
  const out = new Uint8Array(map.length * 16);
  map.forEach((e, t) => out.set(buildTile(romChr, e), t * 16));
  return out;
}

let romChr;
for (const name of Object.keys(CHR_MAP)) {
  if (chrfiles.some(f => f.path.split(/[\\/]/).pop() === name + ".chr")) continue;
  romChr ??= findSmb1Chr(roms);
  if (!romChr) {
    throw new Error("chr/" + name + ".chr is missing and no Super Mario Bros. (World) rom " +
                    "was found. Copy the original rom into the project root as a .nes file.");
  }
  a.segment(name.toUpperCase());
  a.org(0);
  a.byte(Array.from(buildChr(romChr, CHR_MAP[name])));
}
.jsend
